import{_ as t,o as i,c as a,ag as o}from"./chunks/framework.qXLDknWC.js";const h=JSON.parse('{"title":"AI Creation Studio","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai-creation-studio.md","filePath":"features/ai-creation-studio.md"}'),r={name:"features/ai-creation-studio.md"};function n(l,e,s,d,c,g){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-creation-studio" tabindex="-1">AI Creation Studio <a class="header-anchor" href="#ai-creation-studio" aria-label="Permalink to &quot;AI Creation Studio&quot;">​</a></h1><p>The <strong>AI Creation Studio</strong> is a dedicated workspace for generating complete character cards from scratch using AI. Describe your concept or select tags, and the AI generates a name, description, first message, and example dialogue — all in one flow.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>AI Creation Studio requires an AI provider to be configured. See <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a> to get connected first.</p></div><h2 id="opening-the-studio" tabindex="-1">Opening the Studio <a class="header-anchor" href="#opening-the-studio" aria-label="Permalink to &quot;Opening the Studio&quot;">​</a></h2><p>Access the AI Creation Studio from the main vault view:</p><ol><li>Click the <strong>✨ AI Creation Studio</strong> button in the vault header.</li><li>The studio opens in a full-screen workspace with a clean, focused interface.</li></ol><h2 id="input-modes" tabindex="-1">Input Modes <a class="header-anchor" href="#input-modes" aria-label="Permalink to &quot;Input Modes&quot;">​</a></h2><p>The studio supports two ways to define your character concept:</p><h3 id="write-mode" tabindex="-1">Write Mode <a class="header-anchor" href="#write-mode" aria-label="Permalink to &quot;Write Mode&quot;">​</a></h3><p>Type a free-form description of your character idea. The AI uses your text as the creative foundation.</p><p><strong>Example concepts:</strong></p><ul><li>&quot;A cynical dwarven blacksmith with a secret past, living in a mountain fortress who speaks in riddles&quot;</li><li>&quot;A cheerful android barista who dreams of becoming human&quot;</li><li>&quot;A mysterious vampire librarian who collects forbidden knowledge&quot;</li></ul><p><strong>Requirements:</strong></p><ul><li>Minimum 3 words</li><li>The more detail you provide, the better the AI can capture your vision</li></ul><h3 id="tags-mode" tabindex="-1">Tags Mode <a class="header-anchor" href="#tags-mode" aria-label="Permalink to &quot;Tags Mode&quot;">​</a></h3><p>Select from curated tag categories to build your concept visually. Tags are organized into six categories:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Category</th><th style="text-align:left;">Purpose</th><th style="text-align:left;">Examples</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Identity</strong></td><td style="text-align:left;">Core identity traits</td><td style="text-align:left;">Female, Male, Elf, Android, Vampire</td></tr><tr><td style="text-align:left;"><strong>Personality</strong></td><td style="text-align:left;">Character traits</td><td style="text-align:left;">Tsundere, Yandere, Kuudere, Cheerful, Cynical</td></tr><tr><td style="text-align:left;"><strong>Role</strong></td><td style="text-align:left;">Relationship or occupation</td><td style="text-align:left;">Teacher, Knight, Barista, Mother, Rival</td></tr><tr><td style="text-align:left;"><strong>Genre</strong></td><td style="text-align:left;">Setting or theme</td><td style="text-align:left;">Fantasy, Sci-Fi, Modern, Historical</td></tr><tr><td style="text-align:left;"><strong>Tone</strong></td><td style="text-align:left;">Interaction style</td><td style="text-align:left;">Romantic, Dark, Comedic, Wholesome</td></tr><tr><td style="text-align:left;"><strong>Appearance</strong></td><td style="text-align:left;">Physical traits</td><td style="text-align:left;">Tall, Short, Muscular, Petite</td></tr></tbody></table><p><strong>Tag Selection:</strong></p><ul><li>Click tags to select or deselect them</li><li>Select multiple tags per category</li><li>Tags automatically convert to a readable concept (e.g., <code>female_knight</code> → &quot;Female, Knight&quot;)</li><li>Conflicting tags are automatically excluded (e.g., selecting &quot;female&quot; disables &quot;male&quot; and related tags)</li></ul><div class="tip custom-block"><p class="custom-block-title">Switching Modes</p><p>When switching from Tags to Write mode, your selected tags are automatically converted to text and populate the concept field. You can then edit or expand on them.</p></div><h2 id="feeling-lucky" tabindex="-1">Feeling Lucky <a class="header-anchor" href="#feeling-lucky" aria-label="Permalink to &quot;Feeling Lucky&quot;">​</a></h2><p>The <strong>🎲 Feeling Lucky</strong> button (Tags mode only) randomly selects tags across all categories and starts generation immediately.</p><p><strong>How it works:</strong></p><ul><li>Core categories (Identity, Role, Personality): 1–2 tags each</li><li>Supporting categories (Genre, Appearance, Tone): 0–2 tags each</li><li>Respects tag exclusion rules (no conflicting combinations)</li><li>Shows a visual &quot;tag vortex&quot; animation before generation starts (can be disabled in Settings)</li></ul><p><strong>Disabling the Vortex:</strong></p><ol><li>Open <strong>Settings</strong> from the studio header</li><li>Go to the <strong>UI</strong> tab</li><li>Toggle <strong>Show Lucky Vortex</strong> off</li><li>When disabled, Feeling Lucky generates immediately without the animation</li></ol><h2 id="generation-process" tabindex="-1">Generation Process <a class="header-anchor" href="#generation-process" aria-label="Permalink to &quot;Generation Process&quot;">​</a></h2><p>When you click <strong>Generate Character</strong>, the AI creates four fields in sequence:</p><ol><li><strong>Name</strong> — Character&#39;s name</li><li><strong>Description</strong> — Detailed character description</li><li><strong>First Message</strong> — Opening greeting</li><li><strong>Example Dialogue</strong> — Sample conversation demonstrating personality and speech patterns</li></ol><p><strong>During generation:</strong></p><ul><li>Each field streams in real-time as the AI writes</li><li>A progress indicator shows which field is currently generating</li><li>You can <strong>Stop</strong> generation at any time</li><li>The concept or tags used are displayed for reference</li></ul><p><strong>After generation:</strong></p><ul><li>Review the generated content in the preview panel</li><li>Edit any field directly in the preview</li><li>Retry individual fields if you&#39;re not satisfied</li><li>Regenerate fields to get completely new content</li><li>Continue generation if it was stopped early</li></ul><h2 id="preview-editing" tabindex="-1">Preview &amp; Editing <a class="header-anchor" href="#preview-editing" aria-label="Permalink to &quot;Preview &amp; Editing&quot;">​</a></h2><p>The right panel shows a live preview of your character card as it&#39;s generated.</p><p><strong>Preview features:</strong></p><ul><li>Real-time updates as fields are generated</li><li>Click any field to edit it directly</li><li>Changes are saved automatically</li><li>Character count shown for each field</li></ul><p><strong>Field Actions:</strong></p><p>Each completed field has action buttons:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Button</th><th style="text-align:left;">Action</th><th style="text-align:left;">What It Does</th></tr></thead><tbody><tr><td style="text-align:left;">🔄 <strong>Retry</strong></td><td style="text-align:left;">Retry</td><td style="text-align:left;">Re-generate the field if generation failed</td></tr><tr><td style="text-align:left;">✨ <strong>Regenerate</strong></td><td style="text-align:left;">Regenerate</td><td style="text-align:left;">Generate completely new content for this field</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Retry</strong> is for fixing errors. <strong>Regenerate</strong> is for getting a fresh take on a field you don&#39;t like.</p></div><h2 id="saving-to-vault" tabindex="-1">Saving to Vault <a class="header-anchor" href="#saving-to-vault" aria-label="Permalink to &quot;Saving to Vault&quot;">​</a></h2><p>Once generation is complete (or partially complete with at least a name), you can save the character:</p><ol><li>Click <strong>Save to Vault</strong> in the bottom-right corner</li><li>The character is added to your vault immediately</li><li>A success message appears with three options: <ul><li><strong>Open Character</strong> — Jump to the editor to continue working</li><li><strong>Create Another</strong> — Start a new character from scratch</li><li><strong>Library</strong> — Return to the vault view</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">Partial Saves</p><p>You can save a character even if not all fields are generated, as long as it has a name. Missing fields will be empty in the editor.</p></div><h2 id="generation-settings" tabindex="-1">Generation Settings <a class="header-anchor" href="#generation-settings" aria-label="Permalink to &quot;Generation Settings&quot;">​</a></h2><p>The studio uses your configured AI provider and sampler settings. To adjust:</p><ol><li>Click <strong>Settings</strong> in the studio header</li><li>Configure your AI provider, model, and sampler settings</li><li>Changes apply immediately to new generations</li></ol><p>See <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a> and <a href="/CharacterVault/docs/configuration/sampler-settings">Sampler Settings</a> for details.</p><h2 id="api-usage" tabindex="-1">API Usage <a class="header-anchor" href="#api-usage" aria-label="Permalink to &quot;API Usage&quot;">​</a></h2><p>Each character generation uses <strong>a minimum of 4 API calls</strong> — one per field (Name, Description, First Message, Example Dialogue).</p><p><strong>Additional calls occur when:</strong></p><ul><li>Retrying a failed field</li><li>Regenerating a field</li><li>Continuing a stopped generation</li></ul><div class="tip custom-block"><p class="custom-block-title">Cost Awareness</p><p>Generation can consume significant tokens depending on your model and sampler settings. Monitor your API usage if you&#39;re on a metered plan.</p></div><h2 id="tips-for-best-results" tabindex="-1">Tips for Best Results <a class="header-anchor" href="#tips-for-best-results" aria-label="Permalink to &quot;Tips for Best Results&quot;">​</a></h2><p><strong>Write Mode:</strong></p><ul><li>Be specific about personality, setting, and tone</li><li>Include unique quirks or speech patterns</li><li>Mention relationships or background if relevant</li></ul><p><strong>Tags Mode:</strong></p><ul><li>Mix categories for richer characters (e.g., Identity + Personality + Genre)</li><li>Use Appearance and Tone tags to fine-tune the vibe</li><li>Experiment with Feeling Lucky for unexpected combinations</li></ul><p><strong>After Generation:</strong></p><ul><li>Edit fields directly in the preview to refine the output</li><li>Regenerate individual fields if they don&#39;t match your vision</li><li>Save early and continue editing in the main editor for advanced features</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>&quot;AI Provider Not Configured&quot;</strong></p><ul><li>You need to set up your AI provider first</li><li>Click <strong>Configure AI</strong> in the warning banner</li><li>See <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a> for instructions</li></ul><p><strong>Generation fails or returns empty content</strong></p><ul><li>Check your API key and model configuration</li><li>Verify your model supports chat completions</li><li>Try a different model or adjust sampler settings</li></ul><p><strong>Generation is too slow</strong></p><ul><li>Reduce <code>max_tokens</code> in sampler settings</li><li>Use a faster model</li><li>Check your network connection</li></ul><p><strong>Fields don&#39;t match my concept</strong></p><ul><li>Try regenerating individual fields</li><li>Edit the concept to be more specific</li><li>Manually edit fields in the preview</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure your AI provider</a></li><li><a href="/CharacterVault/docs/configuration/sampler-settings">Adjust sampler settings</a></li><li><a href="/CharacterVault/docs/features/editor">Learn about the character editor</a></li><li><a href="/CharacterVault/docs/features/ai-assistant">Use the AI Assistant for refinement</a></li></ul>',72)])])}const p=t(r,[["render",n]]);export{h as __pageData,p as default};
